from pathlib import Path
p=Path('workflow-engine.js');s=p.read_text()
old="function unresolvedMaterialDefects(project){\n  return confirmedDefects(project).filter(record=>{\n    const severity=upper(recordValue(record,'SEVERITY'));\n    const status=upper(recordValue(record,'STATUS'));\n    return ['CRITICAL','MAJOR'].includes(severity)&&!['CLOSED','CLOSED VERIFIED','CLOSED_VERIFIED','RESOLVED','CORRECTED AND VERIFIED','RETIRED'].includes(status);\n  });\n}"
new="function unresolvedMaterialDefects(project){\n  const regressions=records(project,'regressions').filter(r=>upper(recordValue(r,'ACTIVE_RETIRED_STATE')||'ACTIVE')!=='RETIRED'),executions=records(project,'regressionExecutions');\n  return confirmedDefects(project).filter(record=>{\n    const severity=upper(recordValue(record,'SEVERITY')),status=upper(recordValue(record,'STATUS'));if(!['CRITICAL','MAJOR'].includes(severity)||['CLOSED','CLOSED VERIFIED','CLOSED_VERIFIED','RESOLVED','CORRECTED AND VERIFIED','RETIRED'].includes(status))return false;\n    const defectId=recordId(record,'defects'),linked=regressions.filter(r=>String(recordValue(r,'DEFECT_ID')||r.relationships?.DEFECT_ID||'')===defectId);if(!linked.length)return true;\n    return !linked.every(reg=>{const regId=recordId(reg,'regressions'),latest=executions.filter(e=>String(recordValue(e,'REG_ID')||e.relationships?.REG_ID||'')===regId).at(-1);return latest&&upper(recordValue(latest,'PHASE'))!=='PRE_CORRECTION'&&['SATISFIED','SUCCESS','PASSED'].includes(upper(recordValue(latest,'RESULT')));});\n  });\n}"
assert old in s
p.write_text(s.replace(old,new,1))
